\WHILE{$lo \leq hi$}
  \STATE $mid \gets (lo+hi)/2$
  \IF{$A[mid] = x$}
    \RETURN $mid$
  \ELSE
    \STATE $lo \gets mid+1$
  \ENDIF
\ENDWHILE
\RETURN $-1$
\end{algorithmic}
